void MyCallback(object myobject)
{
    // Do whatever you want to happen
}

myEventer.SomeEvent += () =>
{
    // This may be happened on a thread that is not the main Simio run thread
    calendar.ScheduleCurrentEvent(null, MyCallback);
};

void MyCallback(object myobject)
{
    // Because this was scheduled with ScheduleCurrentEvent, it will be executed on the main Simio run thread
    _myEvent.Fire();
}

member.example:
 This example shows how to define a function on some IElementDefinition implementation, given that the IElement type it creates is called MyElement.
 The implementation casts the passed in IElement to MyElement then queries its value directly.
 
 public void DefineSchema(IElementSchema schema)
 {
     schema.ElementFunctions.AddSimpleRealNumberFunction("MyValue", "This returns MyValue for MyElement", new SimioSimpleRealNumberFunc(MyValue));
 }

 public double MyValue(object element)
 {
     var myElement = element as MyElement;
     return myElement.MyValue; // A real number returned by the myElement instance
 }

 This example shows how to define a function on some IElementDefinition implementation, given that the IElement type it creates is called MyElement.
 The implementation casts the passed in IElement to MyElement then queries its value directly.
 
 public void DefineSchema(IElementSchema schema)
 {
     schema.ElementFunctions.AddSimpleStringFunction("MyValue", "This returns MyValue for MyElement", new SimioSimpleStringFunc(MyValue));
 }

 public string MyValue(object element)
 {
     var myElement = element as MyElement;
     return myElement.MyValue; // A string returned by the myElement instance
 }

