member.example:
One could export all logs with an active binding for a given data connector with code such as:

void ExportAllLogsForPlanForDataConnector(IModel model, string dataConnectorName)
{
    var dataConnector = model.ExportDataConnectors[dataConnectorName];
    foreach(var exportableLog in model.Plan.AllExportableLogs)
    {
        if (exportableLog.ExportBindings.ActiveExportBinding?.DataConnector == dataConnector)
        {
            exportableLog.ExportForPlan();
        }
    }
}

