example.code:
public ExitType Execute(IStepExecutionContext context)
{
    var tablePropReader = (ITableReferencePropertyReader)_properties.GetProperty("MyTable");
    var tableRef = tablePropReader.GetTableReference(context);
    
    var newRow = tableRef.AddRow(context);
    foreach(var stateColumn in tableRef.Table.StateColumns)
    {
        newRow.States[stateColumn.Name].StateValue = 42;
    }
}
